import React, { useState, useEffect } from 'react';
import { useParams } from 'react-router-dom';
import { Container, Row, Col, Card, Button, Form, Tab, Tabs } from 'react-bootstrap';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faStar, faStarHalfAlt, faShoppingCart } from '@fortawesome/free-solid-svg-icons';
import axios from 'axios';

interface Review {
  id: number;
  userName: string;
  rating: number;
  comment: string;
  date: string;
}

interface Manga {
  id: number;
  title: string;
  author: string;
  description: string;
  coverImage: string;
  price: number;
  rating: number;
  category: string;
  releaseDate: string;
  publisher: string;
  pages: number;
  reviews: Review[];
}

const MangaDetail: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const [manga, setManga] = useState<Manga | null>(null);
  const [quantity, setQuantity] = useState(1);
  const [relatedManga, setRelatedManga] = useState<Manga[]>([]);

  useEffect(() => {
    const fetchMangaDetail = async () => {
      try {
        // In a real application, replace with your actual API endpoint
        const response = await axios.get(`/api/manga/${id}`);
        setManga(response.data);

        // Fetch related manga
        const relatedResponse = await axios.get(`/api/manga/${id}/related`);
        setRelatedManga(relatedResponse.data);
      } catch (error) {
        console.error('Error fetching manga details:', error);
      }
    };

    fetchMangaDetail();
  }, [id]);

  const renderRatingStars = (rating: number) => {
    const stars: JSX.Element[] = [];
    const fullStars = Math.floor(rating);
    const hasHalfStar = rating % 1 !== 0;

    for (let i = 0; i < fullStars; i++) {
      stars.push(<FontAwesomeIcon key={i} icon={faStar} className="text-warning" />);
    }

    if (hasHalfStar) {
      stars.push(<FontAwesomeIcon key="half" icon={faStarHalfAlt} className="text-warning" />);
    }

    return stars;
  };

  const handleAddToCart = () => {
    // Implement cart functionality
    console.log(`Adding ${quantity} copies of manga ${id} to cart`);
  };

  if (!manga) {
    return <div>Loading...</div>;
  }

  return (
    <Container className="py-4">
      <Row className="mb-4">
        <Col md={4}>
          <Card>
            <Card.Img variant="top" src={manga.coverImage} alt={manga.title} />
          </Card>
        </Col>
        <Col md={8}>
          <h1>{manga.title}</h1>
          <div className="mb-3">
            <span className="me-3">Tác giả: {manga.author}</span>
            <span className="me-3">Thể loại: {manga.category}</span>
          </div>
          <div className="mb-3">
            {renderRatingStars(manga.rating)}
            <span className="ms-2">{manga.rating} / 5</span>
          </div>
          <h2 className="text-primary mb-3">{manga.price.toLocaleString('vi-VN')} đ</h2>
          <div className="d-flex align-items-center mb-3">
            <Form.Control
              type="number"
              min="1"
              value={quantity}
              onChange={(e) => setQuantity(parseInt(e.target.value))}
              style={{ width: '80px' }}
              className="me-3"
            />
            <Button variant="primary" onClick={handleAddToCart}>
              <FontAwesomeIcon icon={faShoppingCart} className="me-2" />
              Thêm vào giỏ hàng
            </Button>
          </div>
        </Col>
      </Row>

      <Tabs defaultActiveKey="description" className="mb-4">
        <Tab eventKey="description" title="Mô tả">
          <div className="p-3">
            <p>{manga.description}</p>
            <h5>Thông tin chi tiết:</h5>
            <ul>
              <li>Nhà xuất bản: {manga.publisher}</li>
              <li>Ngày phát hành: {manga.releaseDate}</li>
              <li>Số trang: {manga.pages}</li>
            </ul>
          </div>
        </Tab>
        <Tab eventKey="reviews" title="Đánh giá">
          <div className="p-3">
            {manga.reviews.map((review) => (
              <Card key={review.id} className="mb-3">
                <Card.Body>
                  <div className="d-flex justify-content-between">
                    <h6>{review.userName}</h6>
                    <small className="text-muted">{review.date}</small>
                  </div>
                  <div className="mb-2">
                    {renderRatingStars(review.rating)}
                  </div>
                  <p>{review.comment}</p>
                </Card.Body>
              </Card>
            ))}
          </div>
        </Tab>
      </Tabs>

      <section>
        <h3 className="mb-3">Truyện liên quan</h3>
        <Row xs={1} md={2} lg={4} className="g-4">
          {relatedManga.map((relatedManga) => (
            <Col key={relatedManga.id}>
              <Card className="h-100">
                <Card.Img variant="top" src={relatedManga.coverImage} alt={relatedManga.title} />
                <Card.Body>
                  <Card.Title>{relatedManga.title}</Card.Title>
                  <div className="mb-2">
                    {renderRatingStars(relatedManga.rating)}
                  </div>
                  <p className="price">{relatedManga.price.toLocaleString('vi-VN')} đ</p>
                </Card.Body>
              </Card>
            </Col>
          ))}
        </Row>
      </section>
    </Container>
  );
};

export default MangaDetail;
